#include <bits/stdc++.h>
using namespace std;

const int MAXN = 1 << 19 | 5;
int n, k, p, max_power, count[MAXN], f[MAXN];
int tmp1[20][MAXN], tmp2[20][MAXN], tmp3[20][MAXN];
long long p_pow;
long long t[20][MAXN];
long long fact[MAXN], inv_fact[MAXN];

long long bin_pow(long long base, long long exp) {
    long long res = 1, cur = base;
    while (exp > 0) {
        if (exp & 1) res = res * cur % p;
        cur = cur * cur % p;
        exp >>= 1;
    }
    return res;
}

void setup() {
    fact[0] = 1;
    for (int i = 1; i <= max_power; i++)
        fact[i] = fact[i - 1] * i % p;
    inv_fact[max_power] = bin_pow(fact[max_power], p - 2);
    for (int i = max_power - 1; i >= 0; i--)
        inv_fact[i] = inv_fact[i + 1] * (i + 1) % p;
}

int get_lower_bound(int x) {
    int res = 1;
    while (res < x) res <<= 1;
    return res;
}

void performFWT(int *arr, int len, bool inv = false) {
    long long *temp = t[0];
    for (int i = 0; i < len; i++) temp[i] = arr[i];
    if (inv)
        for (int i = 1; i < len; i <<= 1)
            for (int j = 0; j < len; j += (i << 1))
                for (int k = j; k < i + j; k++)
                    temp[i + k] -= temp[k];
    else
        for (int i = 1; i < len; i <<= 1)
            for (int j = 0; j < len; j += (i << 1))
                for (int k = j; k < i + j; k++)
                    temp[i + k] += temp[k];
    for (int i = 0; i < len; i++) {
        arr[i] = temp[i] % p;
        if (arr[i] < 0) arr[i] += p;
    }
}

inline void modulate(long long &x) { x >= p_pow ? x -= p_pow : x; }

void combine() {
    for (int j = 0; j <= 19; j++) {
        memset(tmp1[j], 0, sizeof(int[max_power + 1]));
        memset(t[j], 0, sizeof(long long[max_power + 1]));
    }
    for (int j = 0; j <= max_power; j++)
        tmp1[count[j]][j] = f[j];
    for (int j = 0; j <= 19; j++)
        performFWT(tmp1[j], max_power + 1);
    for (int q = 0; q <= 19; q++)
        for (int l = 0; q + l <= 19; l++)
            for (int s = 0; s <= max_power; s++)
                modulate(t[q + l][s] += 1LL * tmp1[q][s] * tmp2[l][s]);
    for (int q = 0; q <= 19; q++)
        for (int s = 0; s <= max_power; s++)
            tmp3[q][s] = t[q][s] % p;
    for (int j = 0; j <= 19; j++)
        performFWT(tmp3[j], max_power + 1, true);
    for (int j = 0; j <= max_power; j++)
        f[j] = tmp3[count[j]][j];
}

void combine_alt() {
    static int tmp[20][MAXN];
    for (int i = 0; i <= 19; i++)
        memset(t[i], 0, sizeof(long long[max_power + 1]));
    for (int q = 0; q <= 19; q++)
        for (int l = 0; q + l <= 19; l++)
            for (int s = 0; s <= max_power; s++)
                modulate(t[q + l][s] += 1LL * tmp2[q][s] * tmp2[l][s]);
    for (int q = 0; q <= 19; q++)
        for (int s = 0; s <= max_power; s++)
            tmp[q][s] = t[q][s] % p;
    for (int i = 0; i <= 19; i++)
        performFWT(tmp[i], max_power + 1, true);
    for (int i = 0; i <= 19; i++)
        memset(tmp2[i], 0, sizeof(int[max_power + 1]));
    for (int i = 0; i <= max_power; i++)
        tmp2[count[i]][i] = tmp[count[i]][i];
    for (int i = 0; i <= 19; i++)
        performFWT(tmp2[i], max_power + 1);
}

int main() {
    scanf("%d%d%d", &n, &k, &p);
    p_pow = 1LL * p * p;
    if (n & 1) {
        printf("%lld", bin_pow(k, n));
        return 0;
    }
    f[0] = 1;
    max_power = get_lower_bound(n + 1) - 1;
    setup();
    for (int i = 0; i <= max_power; i++)
        count[i] = __builtin_popcount(i);
    for (int i = 0; i <= max_power; i++)
        tmp2[count[i]][i] = inv_fact[i];
    for (int i = 0; i <= 19; i++)
        performFWT(tmp2[i], max_power + 1);
    int res_k = k;
    while (k) {
        if (k & 1) combine();
        k >>= 1;
        if (k) combine_alt();
    }
    printf("%lld", (bin_pow(res_k, n) - fact[n] * f[n] % p + p) % p);
    return 0;
}
